func (q Query) ReservedLte(v int32) Query          { return q.Where(Reserved.Lte(v)) }
func (q Query) ReservedIn(v ...int32) Query        { return q.Where(Reserved.In(v...)) }
func (q Query) ReservedNotIn(v ...int32) Query     { return q.Where(Reserved.NotIn(v...)) }
func (q Query) VersionEq(v int32) Query            { return q.Where(Version.Eq(v)) }
func (q Query) VersionNotEq(v int32) Query         { return q.Where(Version.NotEq(v)) }
func (q Query) VersionGt(v int32) Query            { return q.Where(Version.Gt(v)) }
func (q Query) VersionGte(v int32) Query           { return q.Where(Version.Gte(v)) }
func (q Query) VersionLt(v int32) Query            { return q.Where(Version.Lt(v)) }
func (q Query) VersionLte(v int32) Query           { return q.Where(Version.Lte(v)) }
func (q Query) VersionIn(v ...int32) Query         { return q.Where(Version.In(v...)) }
func (q Query) VersionNotIn(v ...int32) Query      { return q.Where(Version.NotIn(v...)) }

const selectPrefix = `SELECT "id", "created_at", "updated_at", "updated_by", "product_id", "on_hand", "reserved", "version" FROM "stock_items"`
const countPrefix = `SELECT count(*) FROM "stock_items"`
const existsPrefix = `SELECT 1 FROM "stock_items"`
const existsSuffix = ` LIMIT 1`
const limitSuffix = ` LIMIT $`
const limitOffsetSuffix = ` LIMIT $ OFFSET $`

// lockSuffix is the row-lock clause per mode, indexed by Query.lock.
// It goes at the very END of the statement — after LIMIT and OFFSET,
// which is what the grammar requires.
var lockSuffix = [8]string{
	``,
	` FOR UPDATE`,
	` FOR UPDATE NOWAIT`,
	` FOR UPDATE SKIP LOCKED`,
	` FOR SHARE`,
	` FOR SHARE NOWAIT`,
	` FOR SHARE SKIP LOCKED`,
	` FOR NO KEY UPDATE`,
}

// lockCaches holds one compiled-statement cache per (lock, offset) pair.
var lockCaches = func() [8][2]*runtime.TreeCache {
	var cs [8][2]*runtime.TreeCache
	for i := range cs {
		cs[i][0], cs[i][1] = runtime.NewTreeCache(), runtime.NewTreeCache()
	}
	cs[0][0], cs[0][1] = cache, offsetCache
	return cs
}()

// orderTable is every ordering this table can express, lowered at build
// time. ORDER BY is chosen per query, so it cannot be a constant — but it
// still must not be built from strings at run time.
var orderTable = [nCols][4]string{
	{"\"id\"", "\"id\" DESC", "\"id\" ASC NULLS FIRST", "\"id\" DESC NULLS LAST"},
	{"\"created_at\"", "\"created_at\" DESC", "\"created_at\" ASC NULLS FIRST", "\"created_at\" DESC NULLS LAST"},
	{"\"updated_at\"", "\"updated_at\" DESC", "\"updated_at\" ASC NULLS FIRST", "\"updated_at\" DESC NULLS LAST"},
	{"\"updated_by\"", "\"updated_by\" DESC", "\"updated_by\" ASC NULLS FIRST", "\"updated_by\" DESC NULLS LAST"},
	{"\"product_id\"", "\"product_id\" DESC", "\"product_id\" ASC NULLS FIRST", "\"product_id\" DESC NULLS LAST"},
	{"\"on_hand\"", "\"on_hand\" DESC", "\"on_hand\" ASC NULLS FIRST", "\"on_hand\" DESC NULLS LAST"},
	{"\"reserved\"", "\"reserved\" DESC", "\"reserved\" ASC NULLS FIRST", "\"reserved\" DESC NULLS LAST"},
	{"\"version\"", "\"version\" DESC", "\"version\" ASC NULLS FIRST", "\"version\" DESC NULLS LAST"},
}

// identTable is each column's bare quoted name, for the left side of a
// row comparison.
var identTable = [nCols]string{
	"\"id\"",
	"\"created_at\"",
	"\"updated_at\"",
	"\"updated_by\"",
	"\"product_id\"",
	"\"on_hand\"",
	"\"reserved\"",
	"\"version\"",
}

var lowering = runtime.Lowering{
	Frag:       fragOf,
	Order:      orderOf,
	OB:         runtime.Order{Lead: " ORDER BY ", Sep: ", "},
	Ident:      func(col uint32) string { return runtime.Pick(identTable[:], col) },
	RowCmp:     runtime.RowCmpOps(" > ", " < "),
	TupleOpen:  "(",
	TupleSep:   ", ",
	TupleClose: ")",
}

func orderOf(dir, col uint32) string {
	if col >= nCols || int(dir) >= len(orderTable[0]) {
		return ""
	}
	return orderTable[col][dir]
}

// fragTable is every predicate this table can produce, lowered at build
// time. Runtime splices; it never formats.
var fragTable = [8][34]runtime.Frag{
	{ // id
		runtime.OpEq:    {A: "\"id\" = $"},
		runtime.OpNotEq: {A: "\"id\" <> $"},
		runtime.OpIn:    {A: "\"id\" = ANY($", B: ")"},
		runtime.OpNotIn: {A: "\"id\" <> ALL($", B: ")"},
	},
	{ // created_at
		runtime.OpEq:    {A: "\"created_at\" = $"},
		runtime.OpNotEq: {A: "\"created_at\" <> $"},
		runtime.OpGt:    {A: "\"created_at\" > $"},
		runtime.OpGte:   {A: "\"created_at\" >= $"},
		runtime.OpLt:    {A: "\"created_at\" < $"},
		runtime.OpLte:   {A: "\"created_at\" <= $"},
	},
	{ // updated_at
		runtime.OpEq:    {A: "\"updated_at\" = $"},
		runtime.OpNotEq: {A: "\"updated_at\" <> $"},
		runtime.OpGt:    {A: "\"updated_at\" > $"},
		runtime.OpGte:   {A: "\"updated_at\" >= $"},
		runtime.OpLt:    {A: "\"updated_at\" < $"},
		runtime.OpLte:   {A: "\"updated_at\" <= $"},
	},
	{ // updated_by
		runtime.OpEq:            {A: "\"updated_by\" = $"},
		runtime.OpNotEq:         {A: "\"updated_by\" <> $"},
		runtime.OpGt:            {A: "\"updated_by\" > $"},
		runtime.OpGte:           {A: "\"updated_by\" >= $"},
		runtime.OpLt:            {A: "\"updated_by\" < $"},
		runtime.OpLte:           {A: "\"updated_by\" <= $"},
		runtime.OpEqLower:       {A: "lower(\"updated_by\") = lower($", B: ")"},
		runtime.OpLike:          {A: "\"updated_by\" LIKE $"},
		runtime.OpILike:         {A: "\"updated_by\" ILIKE $"},
		runtime.OpIn:            {A: "\"updated_by\" = ANY($", B: ")"},
		runtime.OpNotIn:         {A: "\"updated_by\" <> ALL($", B: ")"},
		runtime.OpTextHasPrefix: {A: "\"updated_by\" LIKE (replace(replace(replace($", B: ", '!', '!!'), '%', '!%'), '_', '!_') || '%') ESCAPE '!'"},
		runtime.OpTextHasSuffix: {A: "\"updated_by\" LIKE ('%' || replace(replace(replace($", B: ", '!', '!!'), '%', '!%'), '_', '!_')) ESCAPE '!'"},
		runtime.OpTextContains:  {A: "\"updated_by\" LIKE ('%' || replace(replace(replace($", B: ", '!', '!!'), '%', '!%'), '_', '!_') || '%') ESCAPE '!'"},
	},
	{ // product_id
		runtime.OpEq:    {A: "\"product_id\" = $"},
		runtime.OpNotEq: {A: "\"product_id\" <> $"},
		runtime.OpIn:    {A: "\"product_id\" = ANY($", B: ")"},
		runtime.OpNotIn: {A: "\"product_id\" <> ALL($", B: ")"},
	},
	{ // on_hand
		runtime.OpEq:    {A: "\"on_hand\" = $"},
		runtime.OpNotEq: {A: "\"on_hand\" <> $"},
		runtime.OpGt:    {A: "\"on_hand\" > $"},
		runtime.OpGte:   {A: "\"on_hand\" >= $"},
		runtime.OpLt:    {A: "\"on_hand\" < $"},
		runtime.OpLte:   {A: "\"on_hand\" <= $"},
		runtime.OpIn:    {A: "\"on_hand\" = ANY($", B: ")"},
		runtime.OpNotIn: {A: "\"on_hand\" <> ALL($", B: ")"},
	},
	{ // reserved
		runtime.OpEq:    {A: "\"reserved\" = $"},
		runtime.OpNotEq: {A: "\"reserved\" <> $"},
		runtime.OpGt:    {A: "\"reserved\" > $"},
		runtime.OpGte:   {A: "\"reserved\" >= $"},
		runtime.OpLt:    {A: "\"reserved\" < $"},
		runtime.OpLte:   {A: "\"reserved\" <= $"},
		runtime.OpIn:    {A: "\"reserved\" = ANY($", B: ")"},
		runtime.OpNotIn: {A: "\"reserved\" <> ALL($", B: ")"},
	},
	{ // version
		runtime.OpEq:    {A: "\"version\" = $"},
		runtime.OpNotEq: {A: "\"version\" <> $"},
		runtime.OpGt:    {A: "\"version\" > $"},
		runtime.OpGte:   {A: "\"version\" >= $"},
		runtime.OpLt:    {A: "\"version\" < $"},
		runtime.OpLte:   {A: "\"version\" <= $"},
		runtime.OpIn:    {A: "\"version\" = ANY($", B: ")"},
		runtime.OpNotIn: {A: "\"version\" <> ALL($", B: ")"},
	},
}

func fragOf(op, col uint32) runtime.Frag {
	// Bounded by the table, not nCols: existence pseudo-columns live past
	// the real ones, and only here.
	if int(col) >= len(fragTable) || int(op) >= len(fragTable[0]) {
		return runtime.Frag{}
	}
	return fragTable[col][op]
}

// defaultOrder is what a query with no Order() uses. Never empty.
var defaultOrder = [1]runtime.Tok{
	runtime.MakeOrder(runtime.Asc, 0), // id
}

var (
	cache       = runtime.NewTreeCache()
	offsetCache = runtime.NewTreeCache()
	countCache  = runtime.NewTreeCache()
	existsCache = runtime.NewTreeCache()
)

// Shapes reports how many distinct query structures have compiled.
// `storm lint` uses it to catch a builder minting a statement per request.
func Shapes() int { return cache.Shapes() }

// ShapeFlushes reports how many times a shape cache in this package hit
// runtime.ShapeCap and dropped. Anything but zero means a call site builds
// query structure from request data; export it as a gauge.
func ShapeFlushes() int {
	return cache.Flushes() + offsetCache.Flushes() +
		countCache.Flushes() + existsCache.Flushes() +
		updAllCache.Flushes() + delAllCache.Flushes()
}

// stmtFor compiles a read. LIMIT and LIMIT/OFFSET are different
// statements with different placeholder counts, so they get different
// caches rather than a sentinel token muddying the key.
func stmtFor(toks []runtime.Tok, withOffset bool, lock uint8) *runtime.Stmt {
	i, suffix := 0, limitSuffix
	if withOffset {
		i, suffix = 1, limitOffsetSuffix
	}
	c := lockCaches[lock][i]
	suffix += lockSuffix[lock]
	if st := c.Get(toks); st != nil {
		return st
	}
	return c.Put(toks, runtime.SpliceTree(selectPrefix, toks, lowering, suffix))
}

// existsStmtFor compiles the existence probe: SELECT 1, no ORDER BY,
// LIMIT 1 — the planner stops at the first matching tuple instead of
// sorting every match to return the "first" of an order nobody reads.
func existsStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := existsCache.Get(toks); st != nil {
		return st
	}
	return existsCache.Put(toks, runtime.SpliceTree(existsPrefix, toks, lowering, existsSuffix))
}

func countStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := countCache.Get(toks); st != nil {
		return st
	}
	// A count ignores ordering as well as LIMIT: ordering a scalar is
	// wasted work, and the token stream is trimmed before it gets here.
	return countCache.Put(toks, runtime.SpliceTree(countPrefix, toks, lowering, ""))
}

func (q Query) readStmt(toks []runtime.Tok) *runtime.Stmt {
	return stmtFor(toks, q.offset > 0, q.lock)
}

func (q Query) countStmt(toks []runtime.Tok) *runtime.Stmt  { return countStmtFor(toks) }
func (q Query) existsStmt(toks []runtime.Tok) *runtime.Stmt { return existsStmtFor(toks) }

const (
	distinctOpen = "SELECT DISTINCT ON ("
	distinctSep  = ", "
	distinctTail = ") \"id\", \"created_at\", \"updated_at\", \"updated_by\", \"product_id\", \"on_hand\", \"reserved\", \"version\" FROM \"stock_items\""
)

// distinctCaches are AllDistinctOn's, without and with an offset. The
// key is the stream and then n, which the stream alone does not carry.
var distinctCaches = [2]*runtime.TreeCache{runtime.NewTreeCache(), runtime.NewTreeCache()}

var errDistinctOn = errors.New(
	"storm: AllDistinctOn keeps the first row of each run of the query's first n order terms; n must be between one and the number of terms Order set, and the query must not lock rows")

// distinctStmtFor compiles one (stream, n), once.
func distinctStmtFor(key, toks []runtime.Tok, n int, withOffset bool) *runtime.Stmt {
	i, suffix := 0, limitSuffix
	if withOffset {
		i, suffix = 1, limitOffsetSuffix
	}
	c := distinctCaches[i]
	if st := c.Get(key); st != nil {
		return st
	}
	prefix := distinctOpen
	for _, t := range toks {
		if t.Kind() != runtime.KOrder || n == 0 {
			continue
		}
		if prefix != distinctOpen {
			prefix += distinctSep
		}
		prefix += identTable[t.Col()]
		n--
	}
	return c.Put(key, runtime.SpliceTree(prefix+distinctTail, toks, lowering, suffix))
}

// AllDistinctOn keeps the first row, in the query's order, for each distinct
// value of its first n order terms. Limit and Offset count the rows kept;
// n outside the explicit order, or a row lock, is refused.
func (q Query) AllDistinctOn(ctx context.Context, ex runtime.Executor, n int, dst []Row) ([]Row, error) {
	if err := q.Err(); err != nil {
		return dst, err
	}
	if n < 1 || n > int(q.no) || q.lock != 0 {
		return dst, errDistinctOn
	}
	var buf [21]runtime.Tok
	toks := q.stream(&buf)
	var kb [22]runtime.Tok
	key := kb[:copy(kb[:], toks)+1]
	key[len(key)-1] = runtime.Tok(n)
	st := distinctStmtFor(key, toks, n, q.offset > 0)
	if st.Err != nil {
		return dst, st.Err
	}
	var sl runtime.Slab
	rh, bh := st.ReadHint(q.limit)
	sl.Reserve(bh)
	dst = runtime.Grow(dst, rh)
	n0, s0 := len(dst), sl.Size()
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, Row{})
		if err := scan(rows.RawValues(), &dst[len(dst)-1], &sl); err != nil {
			return dst, err
		}
	}
	st.ObserveRead(len(dst)-n0, sl.Size()-s0)
	return dst, rows.Err()
}

// Composition seams, for the generated CONTEXT package and it alone:
// cross-table statements (a filtered semi-join spans two packages) are
// assembled there from each side's tokens, fragments and bindings. Ids
// only — no SQL text and no value crosses here.

// FragOf is the compiled fragment table, exported for composition.
func FragOf(op, col uint32) runtime.Frag { return fragOf(op, col) }

// Lowering is this package's back-end text, exported for composition.
func Lowering() runtime.Lowering { return lowering }

// StmtPieces are the statement's constant parts, exported for composition.
func StmtPieces() (selectPfx, countPfx, limitSfx string) {
	return selectPrefix, countPrefix, limitSuffix
}

// PredToks appends this query's predicate stream to dst: top-level
// conjuncts reduced to one entry, order excluded.
func (q Query) PredToks(dst []runtime.Tok) []runtime.Tok {
	var buf [21]runtime.Tok
	return append(dst, q.preds(&buf)...)
}

// OrderToks appends this query's ordering — explicit, or the default
// unless Unordered.
func (q Query) OrderToks(dst []runtime.Tok) []runtime.Tok {
	if q.no == 0 {
		if q.noOrder {
			return dst
		}
		return append(dst, defaultOrder[:]...)
	}
	return append(dst, q.otoks[:q.no]...)
}

// Locked and Paged report a row lock and an Offset, which a statement
// composed around this query's read may have no place for.
func (q Query) Locked() bool { return q.lock != 0 }
func (q Query) Paged() bool  { return q.offset != 0 }

// Ordered reports an Order(), which a grouped read composed around this
// query's predicates has no place for.
func (q Query) Ordered() bool { return q.no > 0 }

// BindPreds binds this query's predicate values into b, appending to v.
func (q Query) BindPreds(b *Binder, v []any) []any {
	return append(v, q.bindPreds(b)...)
}

// BindPaging appends the LIMIT (and OFFSET when set) arguments.
func (q Query) BindPaging(b *Binder, v []any) []any {
	b.limit = q.limit
	v = append(v, &b.limit)
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	return v
}

// Shape is a fingerprint of this query's structure — equal shapes share a
// compiled statement. Values do not contribute, which is the point.
func (q Query) Shape() uint64 {
	var buf [21]runtime.Tok
	return runtime.HashToks(q.stream(&buf))
}

// SQL returns the compiled text for this query's structure.
func (q Query) SQL() string {
	var buf [21]runtime.Tok
	return q.readStmt(q.stream(&buf)).SQL
}

// Scan decodes one row from raw wire bytes into r, copying text into sl.
//
// Exported for the context package, which assembles batched results and
// therefore has to decode rows it did not issue the query for.
func Scan(rv [][]byte, r *Row, sl *runtime.Slab) error { return scan(rv, r, sl) }

// scan decodes one row straight from the wire. It errors only for a value
// the Go type cannot carry, such as a numeric past 18 digits or a NaN.
func scan(rv [][]byte, r *Row, sl *runtime.Slab) error {
	if len(rv[0]) != 16 {
		return runtime.ShapeErr("id", "uuid", 16, rv[0])
	}
	copy(r.ID[:], rv[0])
	if len(rv[1]) != 8 {
		return runtime.ShapeErr("created_at", "timestamptz", 8, rv[1])
	}
	r.CreatedAt = runtime.Timestamptz(rv[1])
	if len(rv[2]) != 8 {
		return runtime.ShapeErr("updated_at", "timestamptz", 8, rv[2])
	}
	r.UpdatedAt = runtime.Timestamptz(rv[2])
	r.UpdatedBy = sl.Str(rv[3])
	if len(rv[4]) != 16 {
		return runtime.ShapeErr("product_id", "uuid", 16, rv[4])
	}
	copy(r.ProductID[:], rv[4])
	if len(rv[5]) != 4 {
		return runtime.ShapeErr("on_hand", "int4", 4, rv[5])
	}
	r.OnHand = runtime.Int4(rv[5])
	if len(rv[6]) != 4 {
		return runtime.ShapeErr("reserved", "int4", 4, rv[6])
	}
	r.Reserved = runtime.Int4(rv[6])
	if len(rv[7]) != 4 {
		return runtime.ShapeErr("version", "int4", 4, rv[7])
	}
	r.Version = runtime.Int4(rv[7])
	return nil
}

type binder struct {
	vals   []any
	strs   [6]string
	nums   [6]int64
	raws   [4][16]byte
	tims   [4]time.Time
	anyRaw [3][][16]byte
	anyStr [3][]string
	anyI32 [3][]int32
	limit  int64
	offset int64
}

var binders = runtime.NewPool(func() *binder {
	return &binder{vals: make([]any, 0, 17)}
})

// Binder is the pooled argument buffer.
type Binder = binder

func GetBinder() *Binder  { return binders.Get() }
func PutBinder(b *Binder) { putBinder(b) }

// putBinder drops every reference to caller memory, so a pooled binder pins nothing.
func putBinder(b *binder) {
	clear(b.strs[:])
	clear(b.anyRaw[:])
	clear(b.anyStr[:])
	clear(b.anyI32[:])
	binders.Put(b)
}

// bindPreds binds the predicate values, in stream order, from the binder's
// own copies. Count and Exists stop here: they have no LIMIT or OFFSET.
func (q Query) bindPreds(b *binder) []any {
	v := b.vals[:0]
	var ns, nn, nr, ntm, nar, nas, nai32 uint8
	for i := uint8(0); i < q.nt; i++ {
		t := q.toks[i]
		// A predicate's value or a keyset cursor's: both use the arenas.
		if k := t.Kind(); k != runtime.KLeaf && k != runtime.KCol {
			continue
		}
		switch op := runtime.Op(t.Op()); {
		case runtime.ArglessOp(op):
			continue
		case runtime.ListOp(op):
			switch t.Col() {
			case 0, 4:
				v = runtime.Bind(v, b.anyRaw[:], q.anyRaw[:], &nar)
			case 3:
				v = runtime.Bind(v, b.anyStr[:], q.anyStr[:], &nas)
			case 5, 6, 7:
				v = runtime.Bind(v, b.anyI32[:], q.anyI32[:], &nai32)
			}
			continue
		}
		switch t.Col() {
		case 0, 4:
			v = runtime.Bind(v, b.raws[:], q.raws[:], &nr)
		case 1, 2:
			v = runtime.Bind(v, b.tims[:], q.tims[:], &ntm)
		case 3:
			v = runtime.Bind(v, b.strs[:], q.strs[:], &ns)
		case 5, 6, 7:
			v = runtime.Bind(v, b.nums[:], q.nums[:], &nn)
		}
	}
	b.vals = v
	return v
}

// bind is bindPreds plus the paging arguments, in suffix order.
func (q Query) bind(b *binder) []any {
	v := q.bindPreds(b)
	b.limit = q.limit
	v = append(v, &b.limit)
	// An offset of zero is absent from the statement, so it binds nothing.
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	b.vals = v
	return v
}

// All runs the query and decodes every row.
func (q Query) All(ctx context.Context, ex runtime.Executor, dst []Row) ([]Row, error) {
	var sl runtime.Slab
	return q.AllInto(ctx, ex, dst, &sl)
}

// AllInto lets the caller own the string arena.
func (q Query) AllInto(ctx context.Context, ex runtime.Executor, dst []Row, sl *runtime.Slab) ([]Row, error) {
	if err := q.readErr(); err != nil {
		return dst, err
	}
	var buf [21]runtime.Tok
	st := q.readStmt(q.stream(&buf))
	if st.Err != nil {
		// A malformed token stream is a codegen bug: never run it.
		return dst, st.Err
	}
	rh, bh := st.ReadHint(q.limit)
	sl.Reserve(bh)
	dst = runtime.Grow(dst, rh)
	n0, s0 := len(dst), sl.Size()
	b := binders.Get()
	defer putBinder(b)

	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, Row{})
		if err := scan(rows.RawValues(), &dst[len(dst)-1], sl); err != nil {
			return dst, err
		}
	}
	st.ObserveRead(len(dst)-n0, sl.Size()-s0)
	return dst, rows.Err()
}

// Each runs the query and calls fn with each row in turn, holding one row
// and at most about 64 KiB of its text at a time, however many rows come
// back. The row is fn's to keep. An error from fn stops the read, closes
// the result and is returned as it is.
//
// The result stays open while fn runs, so fn must not use ex for another
// statement when ex is one connection — a transaction — rather than a pool.
func (q Query) Each(ctx context.Context, ex runtime.Executor, fn func(Row) error) error {
	if err := q.readErr(); err != nil {
		return err
	}
	var buf [21]runtime.Tok
	st := q.readStmt(q.stream(&buf))
	if st.Err != nil {
		return st.Err
	}
	b := binders.Get()
	defer putBinder(b)

	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return err
	}
	defer rows.Close()
	var sl runtime.Slab
	// What All learned about this shape, which Reserve caps at one chunk.
	sl.Reserve(st.SlabHint())
	for rows.Next() {
		var r Row
		if err := scan(rows.RawValues(), &r, &sl); err != nil {
			return err
		}
		if err := fn(r); err != nil {
			return err
		}
		if sl.Size() >= runtime.EachSlabCap {
			// Retired, not reset: strings fn kept still point into it.
			// The next one is a single full chunk: a result this long is
			// past growing from 128 bytes.
			sl = runtime.Slab{}
			sl.Reserve(runtime.EachSlabCap)
		}
	}
	st.ObserveSlab(sl.Size())
	return rows.Err()
}

// Rows is Each as an iterator, for range. Breaking out of the loop closes
// the result; an error is yielded once, with a zero Row.
func (q Query) Rows(ctx context.Context, ex runtime.Executor) func(yield func(Row, error) bool) {
	return runtime.Seq(func(fn func(Row) error) error { return q.Each(ctx, ex, fn) })
}

// List runs the query and returns every row: All with no slice to reuse.
func (q Query) List(ctx context.Context, ex runtime.Executor) ([]Row, error) {
	return q.All(ctx, ex, nil)
}

// One returns the first row, if any.
func (q Query) One(ctx context.Context, ex runtime.Executor) (Row, bool, error) {
	var sl runtime.Slab
	var buf [1]Row
	out, err := q.Limit(1).AllInto(ctx, ex, buf[:0], &sl)
	if err != nil || len(out) == 0 {
		return Row{}, false, err
	}
	return out[0], true, nil
}

// Count ignores Limit: counting a truncated set is a bug, not a feature.
func (q Query) Count(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.readErr(); err != nil {
		return 0, err
	}
	if q.lock != 0 {
		return 0, errCountLocked
	}
	var buf [21]runtime.Tok
	st := q.countStmt(q.preds(&buf))
	if st.Err != nil {
		// A malformed token stream is a codegen bug: never run it.
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	// bindPreds, not bind: a count has no LIMIT and no OFFSET. The old
	// form bound everything and sliced the last argument off, which was
	// the limit — unless Offset was set, in which case it silently kept
	// the limit and dropped the offset, and the statement mismatched.
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return 0, err
	}
	defer rows.Close()
	var n int64
	if rows.Next() {
		n = runtime.Int8(rows.RawValues()[0])
	}
	return n, rows.Err()
}

// Exists reports whether any row matches: SELECT 1, no ORDER BY, LIMIT 1.
func (q Query) Exists(ctx context.Context, ex runtime.Executor) (bool, error) {
	if err := q.readErr(); err != nil {
		return false, err
	}
	if q.lock != 0 {
		return false, errExistsLocked
	}
	var buf [21]runtime.Tok
	st := q.existsStmt(q.preds(&buf))
	if st.Err != nil {
		return false, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return false, err
	}
	defer rows.Close()
	return rows.Next(), rows.Err()
}

// Prepare resolves the structure and binds arguments without executing.
func (q Query) Prepare(b *Binder) (string, []any) {
	var buf [21]runtime.Tok
	return q.readStmt(q.stream(&buf)).SQL, q.bind(b)
}

// insertSQL does not vary: the column list is fixed by the table, so
// the placeholders are known at build time and nothing is spliced.
const insertSQL = `INSERT INTO "stock_items" ("id", "created_at", "updated_at", "updated_by", "product_id", "on_hand", "reserved", "version") VALUES ($1, $2, $3, $4, $5, $6, $7, $8) RETURNING "id", "created_at", "updated_at", "updated_by", "product_id", "on_hand", "reserved", "version"`

const updatePrefix = `UPDATE "stock_items" SET `
const deletePrefix = `DELETE FROM "stock_items"`

// Dirty bits. One per updatable column; the set of them is an UPDATE's
// identity, exactly as a token stream is a SELECT's.
const (
	dUpdatedAt uint64 = 1 << 0
	dUpdatedBy uint64 = 1 << 1
	dProductID uint64 = 1 << 2
	dOnHand    uint64 = 1 << 3
	dReserved  uint64 = 1 << 4
)

const nUpdatable = 5

// setFrags is every assignment this table can make, lowered at build time.
var setFrags = [nUpdatable]runtime.Frag{
	{A: "\"updated_at\" = $", B: ""}, // updated_at
	{A: "\"updated_by\" = $", B: ""}, // updated_by
	{A: "\"product_id\" = $", B: ""}, // product_id
	{A: "\"on_hand\" = $", B: ""},    // on_hand
	{A: "\"reserved\" = $", B: ""},   // reserved
}

// exprFrags is the SERVER-side assignment each column may take instead
// of a bound value. A zero Frag means the column admits none. None of
// these end in a placeholder sigil, so none consumes an argument slot.
var exprFrags = [nUpdatable]runtime.Frag{
	{A: "\"updated_at\" = now()", B: ""}, // updated_at = the database's clock
	{},                                   // updated_by has no server-side form
	{},                                   // product_id has no server-side form
	{A: "\"on_hand\" = \"on_hand\" + 1", B: ""},   // on_hand = its own value plus one
	{A: "\"reserved\" = \"reserved\" + 1", B: ""}, // reserved = its own value plus one
}

// addFrags adds a bound amount to a counter's own value. A column set
// this way carries BOTH its dirty and its expr bit — a pair no setter
// can otherwise produce, because each clears the other's — so the
// statement key needs no third mask. A zero Frag means the column
// cannot be added to.
var addFrags = [nUpdatable]runtime.Frag{
	{}, // updated_at cannot be added to
	{}, // updated_by cannot be added to
	{}, // product_id cannot be added to
	{A: "\"on_hand\" = \"on_hand\" + $", B: ""},   // on_hand = its own value plus an amount
	{A: "\"reserved\" = \"reserved\" + $", B: ""}, // reserved = its own value plus an amount
}

// pkFrags addresses one row.
var pkFrags = [1]runtime.Frag{
	{A: "\"id\" = $", B: ""}, // id
}

// versionFrag is the optimistic lock. An update carrying it matches
// no row when somebody else wrote first, which is the whole mechanism.
var versionFrag = runtime.Frag{A: "\"version\" = $", B: ""}

// versionBump increments from the column's own value, never from one
// the client read — two writers who both saw 3 must not both write 4.
var versionBump = runtime.Frag{A: "\"version\" = \"version\" + 1", B: ""}

// Insert bits. A masked INSERT names only the columns the caller
// assigned, so every other column takes its database default — which is
// the only way a DEFAULT gen_random_uuid() can ever fire.
const (
	iID        uint64 = 1 << 0
	iCreatedAt uint64 = 1 << 1
	iUpdatedAt uint64 = 1 << 2
	iUpdatedBy uint64 = 1 << 3
	iProductID uint64 = 1 << 4
	iOnHand    uint64 = 1 << 5
	iReserved  uint64 = 1 << 6
	iVersion   uint64 = 1 << 7
)

const nInsertable = 8

// insCols is the quoted column name for each insert bit.
var insCols = [nInsertable]string{
	"\"id\"",
	"\"created_at\"",
	"\"updated_at\"",
	"\"updated_by\"",
	"\"product_id\"",
	"\"on_hand\"",
	"\"reserved\"",
	"\"version\"",
}

// insParts and insPlaceholder come from the back end at build time; the
// runtime splicer chooses none of them.
var insParts = runtime.InsertParts{Open: " (", Sep: ", ", Mid: ") VALUES (", Close: ")"}
var insPlaceholder = runtime.Placeholder{}

const insPrefix = "INSERT INTO \"stock_items\""
const insReturning = " RETURNING \"id\", \"created_at\", \"updated_at\", \"updated_by\", \"product_id\", \"on_hand\", \"reserved\", \"version\""

var insCache = runtime.NewMaskCache()

// insOpCache is the batch path's, keyed the same way. Separate because
// the statements differ by their RETURNING and one cache would hand a
// batch the statement that asks for rows back.
var insOpCache = runtime.NewMaskCache()
var updCache = runtime.NewMaskCache()

// updOpCache is the batch path's, for the same reason as insOpCache:
// an UPDATE that let the database compute a value reads the row back,
// and a batch does not read rows.
var updOpCache = runtime.NewMaskCache()

// updReturning refreshes the staged row after the database computed
// part of it. Without it m.Row() would hold what the row held BEFORE
// the statement, so a caller reading back the counter it just
// incremented would get the old number and never know.
const updReturning = " RETURNING \"id\", \"created_at\", \"updated_at\", \"updated_by\", \"product_id\", \"on_hand\", \"reserved\", \"version\""

// Masks reports how many distinct UPDATE shapes have compiled.
func Masks() int { return updCache.Masks() }

// Mut is a row staged for update: the values, plus which of them were
// actually assigned. An UPDATE writes the assigned ones and no others,
// so a read-modify-write cannot clobber a column it never looked at.
type Mut struct {
	row   Row
	dirty uint64
	expr  uint64
}

// Mutate stages a row read from the database.
func Mutate(r Row) Mut { return Mut{row: r} }

// There is no MutateKey on this table. The version column makes every
// update an optimistic lock, and a lock needs the version that was
// READ — an address alone would carry zero and match nothing, which
// reads as ErrStaleWrite and tells the caller the wrong story.

// Row returns the staged values.
func (m Mut) Row() Row { return m.row }

// Dirty reports the columns assigned a bound value.
func (m Mut) Dirty() uint64 { return m.dirty }

// Expr reports the columns assigned a server-side expression. Together
// with Dirty it is the statement key: the same column written two ways
// is two different statements, and one cannot bind the other's args.
func (m Mut) Expr() uint64 { return m.expr }

// key is this Mut's statement identity.
func (m Mut) key() runtime.MaskKey {
	return runtime.MaskKey{Dirty: m.dirty, Expr: m.expr}
}

// Setters. There is deliberately no setter for the primary key, for an
// Immutable column, or for the version column: the absence of a method is
// the enforcement, so misuse does not compile rather than failing later.
func (m *Mut) SetUpdatedAt(v time.Time) {
	m.row.UpdatedAt = v
	m.dirty |= dUpdatedAt
	m.expr &^= dUpdatedAt
}

// SetUpdatedAtNow assigns the database's clock, not this process's.
func (m *Mut) SetUpdatedAtNow() {
	m.expr |= dUpdatedAt
	m.dirty &^= dUpdatedAt
}

func (m *Mut) SetUpdatedBy(v string) {
	m.row.UpdatedBy = v
	m.dirty |= dUpdatedBy
	m.expr &^= dUpdatedBy
}

func (m *Mut) SetProductID(v [16]byte) {
	m.row.ProductID = v
	m.dirty |= dProductID
	m.expr &^= dProductID
}

func (m *Mut) SetOnHand(v int32) {
	m.row.OnHand = v
	m.dirty |= dOnHand
	m.expr &^= dOnHand
}

// IncOnHand adds one to the column's own value, in the database.
func (m *Mut) IncOnHand() {
	m.expr |= dOnHand
	m.dirty &^= dOnHand
}

// AddOnHand adds n to the column's OWN value, in the database, for
// the same reason IncOnHand does. It replaces any other assignment
// to the column staged on m, as every setter does.
//
// Until the write, Row() holds n, not the column's value.
func (m *Mut) AddOnHand(n int32) {
	m.row.OnHand = n
	m.dirty |= dOnHand
	m.expr |= dOnHand
}

func (m *Mut) SetReserved(v int32) {
	m.row.Reserved = v
	m.dirty |= dReserved
	m.expr &^= dReserved
}

// IncReserved adds one to the column's own value, in the database.
func (m *Mut) IncReserved() {
	m.expr |= dReserved
	m.dirty &^= dReserved
}

// AddReserved adds n to the column's OWN value, in the database, for
// the same reason IncReserved does. It replaces any other assignment
// to the column staged on m, as every setter does.
//
// Until the write, Row() holds n, not the column's value.
func (m *Mut) AddReserved(n int32) {
	m.row.Reserved = n
	m.dirty |= dReserved
	m.expr |= dReserved
}

// Ins stages a new row, with a setter for every insertable column. A column
// left unset is absent from the statement, so the database default applies;
// a zero value that was set is written.
type Ins struct {
	row Row
	set uint64

	// conflict is the upsert target, as a bit per unique-constraint
	// column set. Zero means a plain insert, and a duplicate is an error
	// — which is the right default: silently updating a row you meant to
	// create is a data-loss bug that looks like success.
	conflict uint8

	// add marks the assigned columns an upsert ACCUMULATES into rather
	// than overwrites. Part of the statement key, beside the mask.
	add uint64
}

// Create stages a new row.
func Create() Ins { return Ins{} }

// Assigned reports the mask, which is also the statement key.
func (n Ins) Assigned() uint64 { return n.set }

// insertArgs appends the values n assigns, in column order.
func (n *Ins) insertArgs(args []any) []any {
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.UpdatedBy)
		case 4:
			args = append(args, n.row.ProductID)
		case 5:
			args = append(args, n.row.OnHand)
		case 6:
			args = append(args, n.row.Reserved)
		case 7:
			args = append(args, n.row.Version)
		}
	}
	return args
}

func (n *Ins) SetID(v [16]byte) {
	n.row.ID = v
	n.set |= iID
}

func (n *Ins) SetCreatedAt(v time.Time) {
	n.row.CreatedAt = v
	n.set |= iCreatedAt
}

func (n *Ins) SetUpdatedAt(v time.Time) {
	n.row.UpdatedAt = v
	n.set |= iUpdatedAt
}

func (n *Ins) SetUpdatedBy(v string) {
	n.row.UpdatedBy = v
	n.set |= iUpdatedBy
}

func (n *Ins) SetProductID(v [16]byte) {
	n.row.ProductID = v
	n.set |= iProductID
}

func (n *Ins) SetOnHand(v int32) {
	n.row.OnHand = v
	n.set |= iOnHand
	n.add &^= iOnHand
}

// AddOnHandOnConflict inserts v or, when an OnConflict target updates the
// existing row, adds v to it in the same statement. Without a target, or
// with DoNothing, it is SetOnHand.
func (n *Ins) AddOnHandOnConflict(v int32) {
	n.row.OnHand = v
	n.set |= iOnHand
	n.add |= iOnHand
}

func (n *Ins) SetReserved(v int32) {
	n.row.Reserved = v
	n.set |= iReserved
	n.add &^= iReserved
}

// AddReservedOnConflict inserts v or, when an OnConflict target updates the
// existing row, adds v to it in the same statement. Without a target, or
// with DoNothing, it is SetReserved.
func (n *Ins) AddReservedOnConflict(v int32) {
	n.row.Reserved = v
	n.set |= iReserved
	n.add |= iReserved
}

func (n *Ins) SetVersion(v int32) {
	n.row.Version = v
	n.set |= iVersion
}

// The conflict encoding: 0 none, 1 DO NOTHING on any unique index,
// 2+2*i target i DO UPDATE, 3+2*i target i DO NOTHING.
const conflictAny = 1

// upsertTail builds the ON CONFLICT clause for one encoded conflict and
// insert mask. Only ASSIGNED columns are overwritten.
//
// add marks the assigned columns that ACCUMULATE instead: the row
// that already exists keeps its value plus the one this insert
// carried. See the Add…OnConflict setters.
func upsertTail(conflict uint8, mask uint64, add uint64) string {
	if conflict == conflictAny {
		return " ON CONFLICT DO NOTHING"
	}
	spec, i := conflictSpecs[(conflict-2)/2], (conflict-2)/2
	if conflict%2 == 1 {
		return spec + " DO NOTHING"
	}
	set := assignable(i, mask)
	if len(set) == 0 {
		// Nothing to overwrite. DO UPDATE SET with an empty list is not
		// SQL, and leaving the row alone is what the caller asked for.
		return spec + " DO NOTHING"
	}
	return spec + " DO UPDATE SET " + joinAssign(set, add)
}

// conflictSpecs is one inference specification per target; a partial
// unique index carries its predicate.
var conflictSpecs = []string{
	" ON CONFLICT (\"id\")",
	" ON CONFLICT (\"product_id\")",
}

// assignable is the columns target i may overwrite, given the mask.
func assignable(i uint8, mask uint64) []string {
	set := make([]string, 0, 5)
	for j, bit := range assignBits[i] {
		if mask&(1<<bit) != 0 {
			set = append(set, assignNames[i][j])
		}
	}
	return set
}

// assignBits and assignNames are, per target, the insert bit and the name
// of each column it may overwrite. An empty row is a target whose key
// covers every updatable column.
var assignBits = [2][]uint8{
	{2, 3, 4, 5, 6},
	{2, 3, 5, 6},
}

var assignNames = [2][]string{
	{"updated_at", "updated_by", "product_id", "on_hand", "reserved"},
	{"updated_at", "updated_by", "on_hand", "reserved"},
}

// OnConflictID upserts on the unique index over (id).
// Unassigned columns of the existing row are kept; DoNothing() keeps it all.
func (n *Ins) OnConflictID() *Ins {
	n.conflict = 2
	return n
}

// OnConflictProductID upserts on the unique index over (product_id).
// Unassigned columns of the existing row are kept; DoNothing() keeps it all.
func (n *Ins) OnConflictProductID() *Ins {
	n.conflict = 4
	return n
}

// DoNothing makes the insert a no-op when the row is already there. Alone
// it covers any unique index; after OnConflictID() only that one.
// Insert then returns runtime.ErrNoRows when nothing was written.
func (n *Ins) DoNothing() *Ins {
	if n.conflict < 2 {
		n.conflict = conflictAny
		return n
	}
	n.conflict |= 1
	return n
}

// joinAssign renders the DO UPDATE SET list for the columns the caller
// assigned. The punctuation comes from the back end, never from here.
func joinAssign(set []string, add uint64) string {
	out := ""
	for i, c := range set {
		if i > 0 {
			out += ", "
		}
		if a, ok := assignAdded(c, add); ok {
			out += a
			continue
		}
		out += assignExcluded(c)
	}
	return out
}

// assignAdded is the accumulating assignment for column c, when the
// caller asked for one: the existing row's value plus the rejected
// row's, added by the database in the same statement, so two
// concurrent upserts both land rather than one overwriting the other.
func assignAdded(c string, add uint64) (string, bool) {
	switch c {
	case "on_hand":
		return "\"on_hand\" = \"stock_items\".\"on_hand\" + EXCLUDED.\"on_hand\"", add&iOnHand != 0
	case "reserved":
		return "\"reserved\" = \"stock_items\".\"reserved\" + EXCLUDED.\"reserved\"", add&iReserved != 0
	}
	return "", false
}

var assignFor = map[string]string{
	"updated_at": "\"updated_at\" = EXCLUDED.\"updated_at\"",
	"updated_by": "\"updated_by\" = EXCLUDED.\"updated_by\"",
	"product_id": "\"product_id\" = EXCLUDED.\"product_id\"",
	"on_hand":    "\"on_hand\" = EXCLUDED.\"on_hand\"",
	"reserved":   "\"reserved\" = EXCLUDED.\"reserved\"",
}

func assignExcluded(c string) string { return assignFor[c] }

func stmtForInsert(mask uint64, conflict uint8, add uint64) *runtime.Stmt {
	// The conflict clause is part of the statement, so it must be part of
	// the key. Packing it above the column bits keeps one cache for both.
	key := mask | uint64(conflict)<<nInsertable
	// Accumulating only means something in a DO UPDATE (an even code
	// from 2): anywhere else it is an ordinary insert of the value, and
	// keying it apart would compile the same statement twice.
	if conflict < 2 || conflict%2 == 1 {
		add = 0
	}
	add &= mask
	if st := insCache.Get(runtime.MaskKey{Dirty: key, Expr: add}); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := insReturning
	if conflict > 0 {
		suffix = upsertTail(conflict, mask, add) + insReturning
	}
	return insCache.Put(runtime.MaskKey{Dirty: key, Expr: add}, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// Insert writes the assigned columns and reads every column back, so
// database-computed values land in the returned Row rather than needing a
// second SELECT that would race every other writer.
func (n *Ins) Insert(ctx context.Context, ex runtime.Executor) (Row, error) {
	if n.set == 0 {
		return Row{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsert(n.set, n.conflict, n.add)
	if st.Err != nil {
		// A malformed token stream is a codegen bug: never run it.
		return Row{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	args = n.insertArgs(args)
	var out Row
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return out, err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return out, err
		}
		if n.conflict != 0 && n.conflict%2 == 1 {
			// DO NOTHING suppresses RETURNING, so no row means the row was
			// already there — the success case of an idempotent insert.
			return out, runtime.ErrConflict
		}
		return out, runtime.ErrNoRow
	}
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &out, &sl); err != nil {
		return out, err
	}
	return out, rows.Err()
}

// Inserts reports how many distinct INSERT column sets have compiled.
func Inserts() int { return insCache.Masks() }

// Insert writes every insertable column, zero values included, and reads
// the row back so database defaults land in r.
func Insert(ctx context.Context, ex runtime.Executor, r *Row) error {
	args := make([]any, 0, 8)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.UpdatedBy)
	args = append(args, r.ProductID)
	args = append(args, r.OnHand)
	args = append(args, r.Reserved)
	args = append(args, r.Version)
	rows, err := ex.Query(ctx, insertSQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The returned strings live as long as this Slab, and the Slab lives
	// as long as r — a Row from an insert owns its own arena, unlike a Row
	// from a scan, which shares the result set's.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), r, &sl); err != nil {
		return err
	}
	return rows.Err()
}

// copyCols is the fixed column list of a bulk load. Unlike Ins there is
// no mask: COPY sends one shape for the whole stream, so every row must
// supply every column and database defaults do not apply. Fill the row
// yourself, or use Create() per row and give up the bulk path.
var copyCols = []string{
	"id",
	"created_at",
	"updated_at",
	"updated_by",
	"product_id",
	"on_hand",
	"reserved",
	"version",
}

// rowSource walks a []Row for CopyFrom without copying any of it.
type rowSource struct {
	rows []Row
	i    int
	buf  [8]any
}

func (s *rowSource) Next() bool {
	s.i++
	return s.i <= len(s.rows)
}

// Values reuses one buffer of pointers into the caller's rows: no copy, and
// no allocation per value.
func (s *rowSource) Values() []any {
	r := &s.rows[s.i-1]
	s.buf[0] = &r.ID
	s.buf[1] = &r.CreatedAt
	s.buf[2] = &r.UpdatedAt
	s.buf[3] = &r.UpdatedBy
	s.buf[4] = &r.ProductID
	s.buf[5] = &r.OnHand
	s.buf[6] = &r.Reserved
	s.buf[7] = &r.Version
	return s.buf[:]
}

func (s *rowSource) Err() error { return nil }

// InsertAll bulk-loads rows through COPY in one round trip. It reads nothing
// back, so the primary key must be set on every row.
func InsertAll(ctx context.Context, ex runtime.Executor, rows []Row) (int64, error) {
	if len(rows) == 0 {
		return 0, nil
	}
	src := &rowSource{rows: rows}
	return ex.CopyFrom(ctx, "stock_items", copyCols, src)
}

// InsertOp is an insert as a queueable statement. It writes every insertable
// column, so a batch shares one statement, and reports a count, not rows.
func InsertOp(r Row) runtime.BatchOp {
	const mask = 1<<nInsertable - 1 // every insertable column
	st := stmtForInsertNoReturn(mask, 0, 0)
	args := make([]any, 0, 8)
	args = append(args, r.ID)
	args = append(args, r.CreatedAt)
	args = append(args, r.UpdatedAt)
	args = append(args, r.UpdatedBy)
	args = append(args, r.ProductID)
	args = append(args, r.OnHand)
	args = append(args, r.Reserved)
	args = append(args, r.Version)
	return runtime.BatchOp{SQL: st.SQL, Args: args}
}

// Op is this Ins as a queueable statement, mask and conflict clause included:
// the bulk upsert. One statement per distinct (mask, conflict) pair. The batch
// reports counts, so a skipped DO NOTHING row is a zero.
func (n *Ins) Op() (runtime.BatchOp, error) {
	if n.set == 0 {
		return runtime.BatchOp{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsertNoReturn(n.set, n.conflict, n.add)
	if st.Err != nil {
		return runtime.BatchOp{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	args = n.insertArgs(args)
	return runtime.BatchOp{SQL: st.SQL, Args: args}, nil
}

// stmtForInsertNoReturn is stmtForInsert without RETURNING, for the
// batch path. Its own cache: the two differ by a suffix, and sharing
// one would hand a batch the statement that asks for rows back.
func stmtForInsertNoReturn(mask uint64, conflict uint8, add uint64) *runtime.Stmt {
	// The conflict clause is part of the statement, so it must be part of
	// the key. Packing it above the column bits keeps one cache for both.
	key := mask | uint64(conflict)<<nInsertable
	// Accumulating only means something in a DO UPDATE (an even code
	// from 2): anywhere else it is an ordinary insert of the value, and
	// keying it apart would compile the same statement twice.
	if conflict < 2 || conflict%2 == 1 {
		add = 0
	}
	add &= mask
	if st := insOpCache.Get(runtime.MaskKey{Dirty: key, Expr: add}); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := ""
	if conflict > 0 {
		suffix = upsertTail(conflict, mask, add)
	}
	return insOpCache.Put(runtime.MaskKey{Dirty: key, Expr: add}, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// UpdateOp is this Mut's update as a queueable statement. Check the count the
// batch reports: a stale write there is a zero, not an error, and the staged
// row is not refreshed.
func (m *Mut) UpdateOp() (runtime.BatchOp, bool) {
	if m.dirty == 0 && m.expr == 0 {
		return runtime.BatchOp{}, false
	}
	st := stmtForKey(m.key(), false)
	args := make([]any, 0, st.NArg)
	args = m.updateArgs(args)
	args = append(args, m.row.ID)
	args = append(args, m.row.Version)
	return runtime.BatchOp{SQL: st.SQL, Args: args}, true
}

// DeleteOp is a delete as a queueable statement.
func DeleteOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: deleteSQL, Args: []any{iD}}
}

// Table is the table these statements write, so a Unit can order a mixed
// batch by foreign key without knowing what any of them are.
const Table = "stock_items"

// stmtForKey compiles the UPDATE for one (dirty, expr) pair, once.
//
// ret picks the cache as well as the suffix. The batch path passes
// false — it cannot read rows back, so it must not ask for them.
func stmtForKey(k runtime.MaskKey, ret bool) *runtime.Stmt {
	cache := updCache
	if !ret {
		cache = updOpCache
	}
	if st := cache.Get(k); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		// An expression wins: a column set both ways cannot happen,
		// because each setter clears the other's bit.
		switch {
		case k.Expr&k.Dirty&(1<<uint(i)) != 0:
			set = append(set, addFrags[i])
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	set = append(set, versionBump)
	where := make([]runtime.Frag, 0, 2)
	where = append(where, pkFrags[:]...)
	where = append(where, versionFrag)
	// Only an expression needs reading back. A plain UPDATE already
	// knows every value it wrote, so it pays no RETURNING.
	suffix := ""
	if ret && k.Expr != 0 {
		suffix = updReturning
	}
	return cache.Put(k, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
		{Lead: " WHERE ", Sep: " AND ", Frags: where},
	}, suffix))
}

// Update writes the assigned columns of one row.
//
// The version column makes it an optimistic lock: a row no longer at the
// version that was read is runtime.ErrStaleWrite. Re-read and retry.
// Assigning nothing issues no statement and is not an error.
// A value the database computes is read back, so m.Row() is current.
func (m *Mut) Update(ctx context.Context, ex runtime.Executor) error {
	if m.dirty == 0 && m.expr == 0 {
		return nil
	}
	st := stmtForKey(m.key(), true)
	if st.Err != nil {
		// A malformed token stream is a codegen bug: never run it.
		return st.Err
	}
	args := make([]any, 0, st.NArg)
	args = m.updateArgs(args)
	args = append(args, m.row.ID)
	args = append(args, m.row.Version)
	if m.expr != 0 {
		return m.updateReturning(ctx, ex, st, args)
	}
	n, err := ex.Exec(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrStaleWrite
	}
	m.dirty = 0
	m.expr = 0
	m.row.Version++ // the database incremented it; keep the staged row usable
	return nil
}

// updateReturning runs an UPDATE the database computed part of, and reads
// the whole row back into the staged copy.
func (m *Mut) updateReturning(ctx context.Context, ex runtime.Executor, st *runtime.Stmt, args []any) error {
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrStaleWrite
	}
	// The staged row owns this arena, the way an inserted row does.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &m.row, &sl); err != nil {
		return err
	}
	if err := rows.Err(); err != nil {
		return err
	}
	m.dirty = 0
	m.expr = 0
	return nil
}

var deleteSQL = runtime.SpliceSections(deletePrefix, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: pkFrags[:]},
}, "").SQL

// Delete removes one row by primary key. A row that was already gone is
// runtime.ErrNoRow, not success: a caller deleting something that is not
// there usually has a bug, and swallowing it hides the bug.
func Delete(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, deleteSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}

// Set-based writes. Two caches of their own, keyed like the read
// caches by the predicate stream — UpdateAll's prefixed with the
// assignment masks, which are as much its identity as the predicates.
var (
	updAllCache = runtime.NewTreeCache()
	delAllCache = runtime.NewTreeCache()
)

// UpdateHead is UpdateAll's statement without its predicates, for the
// context package to narrow with a composed read: the UPDATE … SET, the
// identity a statement built from it is cached under, and the values m
// assigns. ok is false when m assigns nothing.
func (m Mut) UpdateHead() (head *runtime.Stmt, key [4]runtime.Tok, args []any, ok bool) {
	if m.dirty == 0 && m.expr == 0 {
		return nil, key, nil, false
	}
	key[0], key[1] = runtime.Tok(m.dirty), runtime.Tok(m.dirty>>32)
	key[2], key[3] = runtime.Tok(m.expr), runtime.Tok(m.expr>>32)
	return updHead(m.key()), key, m.updateArgs(nil), true
}

// updateArgs appends the values m assigns, in SET order.
func (m Mut) updateArgs(args []any) []any {
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.UpdatedBy)
		case 2:
			args = append(args, m.row.ProductID)
		case 3:
			args = append(args, m.row.OnHand)
		case 4:
			args = append(args, m.row.Reserved)
		}
	}
	return args
}

// Shaped reports a Limit, Offset or row lock, which shape a read and
// which a set-based write composed around this query has no place for.
func (q Query) Shaped() bool {
	return q.limit != 1000 || q.offset != 0 || q.lock != 0
}

// writeAllErr is what UpdateAll and DeleteAll refuse.
func (q Query) writeAllErr() error {
	if err := q.Err(); err != nil {
		return err
	}
	if q.nt == 0 {
		return runtime.ErrUnfilteredWrite
	}
	if q.limit != 1000 || q.offset != 0 || q.lock != 0 {
		return runtime.ErrPagedWrite
	}
	return nil
}

var updHeadCache = runtime.NewMaskCache()

// updHead is the UPDATE … SET of one assignment mask, before the
// predicates or the read that narrow it.
func updHead(k runtime.MaskKey) *runtime.Stmt {
	if st := updHeadCache.Get(k); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		switch {
		case k.Expr&k.Dirty&(1<<uint(i)) != 0:
			set = append(set, addFrags[i])
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	// Every row written moves its version on, so a reader holding one
	// of them loses its optimistic lock — exactly as if Update had run.
	set = append(set, versionBump)
	return updHeadCache.Put(k, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
	}, ""))
}

// updAllStmtFor compiles one (assignments, predicates) pair, once.
func updAllStmtFor(k runtime.MaskKey, preds []runtime.Tok) *runtime.Stmt {
	return updAllStmtIn(updAllCache, "", k, preds)
}

func updAllStmtIn(c *runtime.TreeCache, suffix string, k runtime.MaskKey, preds []runtime.Tok) *runtime.Stmt {
	var key [25]runtime.Tok
	key[0], key[1] = runtime.Tok(k.Dirty), runtime.Tok(k.Dirty>>32)
	key[2], key[3] = runtime.Tok(k.Expr), runtime.Tok(k.Expr>>32)
	n := 4 + copy(key[4:], preds)
	if st := c.Get(key[:n]); st != nil {
		return st
	}
	head := updHead(k)
	if head.Err != nil {
		return head
	}
	return c.Put(key[:n], runtime.SpliceTreeFrom(head.SQL, preds, lowering, suffix, head.NArg))
}

// UpdateAll writes m's assigned columns to every row the query
// matches, in ONE statement, and reports how many it wrote:
//
//	n, err := New().Where(…).UpdateAll(ctx, ex, m)
//
// Nothing assigned issues no statement and reports 0. The query needs a
// predicate (runtime.ErrUnfilteredWrite) and no Limit, Offset or row lock
// (runtime.ErrPagedWrite).
// The version column is bumped on every row and checked on none.
func (q Query) UpdateAll(ctx context.Context, ex runtime.Executor, m Mut) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	if m.dirty == 0 && m.expr == 0 {
		return 0, nil
	}
	var buf [21]runtime.Tok
	st := updAllStmtFor(m.key(), q.preds(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	args := append(m.updateArgs(make([]any, 0, st.NArg)), q.bindPreds(b)...)
	return ex.Exec(ctx, st.SQL, args)
}

func delAllStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := delAllCache.Get(toks); st != nil {
		return st
	}
	return delAllCache.Put(toks, runtime.SpliceTree(deletePrefix, toks, lowering, ""))
}

// DeleteAll removes every row the query matches, in ONE statement,
// and reports how many it removed.
// The query needs a predicate (runtime.ErrUnfilteredWrite) and no Limit,
// Offset or row lock (runtime.ErrPagedWrite).
func (q Query) DeleteAll(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	var buf [21]runtime.Tok
	st := delAllStmtFor(q.preds(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	return ex.Exec(ctx, st.SQL, q.bindPreds(b))
}

// The step this table's UpdateAll is, and the statements written after
// another table's step.
var updStepCache = runtime.NewTreeCache()

const stepReturning = ` RETURNING "id"`

// UpdateAllStep is UpdateAll as a step. It refuses what UpdateAll refuses,
// and refuses nothing assigned with runtime.ErrNothingAssigned.
func (q Query) UpdateAllStep(m Mut) runtime.Step {
	return func(run func(string, []any) error) error {
		if err := q.writeAllErr(); err != nil {
			return err
		}
		if m.dirty == 0 && m.expr == 0 {
			return runtime.ErrNothingAssigned
		}
		var buf [21]runtime.Tok
		st := updAllStmtIn(updStepCache, stepReturning, m.key(), q.preds(&buf))
		if st.Err != nil {
			return st.Err
		}
		b := binders.Get()
		defer putBinder(b)
		args := make([]any, 0, st.NArg)
		args = m.updateArgs(args)
		return run(st.SQL, append(args, q.bindPreds(b)...))
	}
}

// ExistsStep is the existence probe as a step: at most one row, when
// the query matches any. A write after it can act on whether it did.
func (q Query) ExistsStep() runtime.Step {
	return func(run func(string, []any) error) error {
		if err := q.Err(); err != nil {
			return err
		}
		if q.lock != 0 {
			return errExistsLocked
		}
		var buf [21]runtime.Tok
		st := existsStmtFor(q.preds(&buf))
		if st.Err != nil {
			return st.Err
		}
		b := binders.Get()
		defer putBinder(b)
		return run(st.SQL, q.bindPreds(b))
	}
}
